// ─────────────────────────────────────────────────────────────
// Prompt injection protection
// ─────────────────────────────────────────────────────────────
function sanitizeForPrompt(text, maxLen = 2000) {
  if (typeof text !== "string") return "";
  return text.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "") // strip control chars (keep \t \n \r)
  .replace(/\r\n|\r/g, "\n").slice(0, maxLen);
}

// ─────────────────────────────────────────────────────────────
// Multi-key AI storage helpers
// ─────────────────────────────────────────────────────────────
const AI_KEYS_STORE = "wa_ai_keys";
const AI_ACTIVE_STORE = "wa_ai_active_id";

function loadAiKeys() {
  try {
    const s = localStorage.getItem(AI_KEYS_STORE);
    if (s) return JSON.parse(s);
  } catch {}
  const provider = localStorage.getItem("wa_ai_provider") || "";
  const key = localStorage.getItem("wa_ai_key") || "";
  if (provider && key) {
    const keys = [{ id: "legacy_1", provider, key }];
    try { localStorage.setItem(AI_KEYS_STORE, JSON.stringify(keys)); localStorage.setItem(AI_ACTIVE_STORE, "legacy_1"); } catch {}
    return keys;
  }
  return [];
}

function getActiveAiKey() {
  const keys = loadAiKeys();
  if (!keys.length) return null;
  const activeId = localStorage.getItem(AI_ACTIVE_STORE) || "";
  return keys.find(k => k.id === activeId) || keys[0];
}

// ─────────────────────────────────────────────────────────────
// Multi-provider AI grader
// ─────────────────────────────────────────────────────────────
async function gradeWithAI(prompt) {
  const proxyUrl = localStorage.getItem("wa_ai_proxy") || "";
  if (proxyUrl) {
    const provider = localStorage.getItem("wa_ai_provider") || "";
    const r = await fetch(proxyUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ provider, prompt }),
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || `Proxy error ${r.status}`);
    return d.text;
  }
  const active = getActiveAiKey();
  if (!active || !active.provider) throw new Error("no_key");
  const provider = active.provider;
  const key = active.key || "";
  if (provider === "openai") {
    const r = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${key}`
      },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: [{
          role: "user",
          content: prompt
        }],
        max_tokens: 900
      })
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error?.message || "OpenAI error");
    return d.choices[0].message.content;
  }
  if (provider === "anthropic") {
    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": key,
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true"
      },
      body: JSON.stringify({
        model: "claude-haiku-4-5-20251001",
        max_tokens: 900,
        messages: [{
          role: "user",
          content: prompt
        }]
      })
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error?.message || "Anthropic error");
    return d.content[0].text;
  }
  if (provider === "groq") {
    const r = await fetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${key}`
      },
      body: JSON.stringify({
        model: "llama-3.3-70b-versatile",
        messages: [{
          role: "user",
          content: prompt
        }],
        max_tokens: 900,
        temperature: 0.3
      })
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error?.message || `Groq error ${r.status}`);
    return d.choices[0].message.content;
  }
  if (provider === "gemini") {
    const models = ["gemini-2.0-flash-lite", "gemini-1.5-flash-latest", "gemini-1.5-flash-8b"];
    let lastErr = null;
    for (const model of models) {
      try {
        const r = await fetch(`https://generativelanguage.googleapis.com/v1/models/${model}:generateContent?key=${key}`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            contents: [{
              parts: [{
                text: prompt
              }]
            }],
            generationConfig: {
              maxOutputTokens: 900,
              temperature: 0.3
            }
          })
        });
        const d = await r.json();
        if (!r.ok) {
          lastErr = new Error(d.error?.message || `Gemini ${model} error ${r.status}`);
          continue;
        }
        return d.candidates[0].content.parts[0].text;
      } catch (e) {
        lastErr = e;
      }
    }
    throw lastErr || new Error("Gemini: no working model found");
  }
  throw new Error("Noma'lum provider");
}

