function WAnimStyle(){
  return React.createElement("style",null,
`@keyframes wa-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@keyframes wa-glow{0%,100%{opacity:.45;transform:scale(1)}50%{opacity:1;transform:scale(1.3)}}
@keyframes wa-flow{0%{left:1%;opacity:0}12%{opacity:1}88%{opacity:1}100%{left:95%;opacity:0}}
@keyframes wa-dash{to{stroke-dashoffset:-18}}
.wa-rise{animation:wa-rise .5s cubic-bezier(.2,.8,.2,1) both}
.wa-card{transition:transform .2s ease,border-color .2s ease}
.wa-card:hover{transform:translateY(-3px)}
.wa-step{transition:all .4s ease;opacity:.4}
.wa-step.lit{opacity:1}
.wa-dot{width:8px;height:8px;border-radius:50%;animation:wa-glow 1s infinite}
.wa-wire{position:relative;height:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);border-radius:2px}
.wa-pkt{position:absolute;top:50%;width:9px;height:9px;border-radius:50%;transform:translate(-50%,-50%);animation:wa-flow 2.4s linear infinite}
@media (prefers-reduced-motion:reduce){.wa-rise,.wa-pkt,.wa-dot,.wa-card{animation:none!important}.wa-pkt{left:47%}}`);
}
